/**
 * Custom NodeMaterial for rendering Gaussian Splats.
 *
 * This material handles:
 * - Billboard quad generation from sorted splat indices
 * - Ellipse computation from 2D covariance matrix
 * - Gaussian alpha falloff evaluation
 * - Proper alpha blending for transparency
 *
 * @class GaussianSplatsMaterial
 * @extends NodeMaterial
 * @short Material for rendering Gaussian Splats with anisotropic ellipses and alpha blending.
 * @category Materials
 * @tags WebGPU
 */
export class GaussianSplatsMaterial {
    static get type(): string;
    /**
     * Create a Gaussian Splats material.
     *
     * @param {GaussianSplats} splats The GaussianSplats instance.
     * @param {Object} [options={}] Material options.
     * @param {string} [options.lightingMode='unlit'] Lighting mode: 'unlit' (DC+SH combined, no PBR) or 'lit' (DC as diffuse albedo, SH as specular color).
     * @param {number} [options.alphaClip=0.05] Base opacity threshold - entire splats with opacity below this are culled (0 = disabled).
     * @param {number} [options.minPixelRadius=2.0] Minimum splat radius in pixels - splats smaller than this are culled (removes noise).
     * @param {number} [options.maxPixelRadius=1000] Maximum splat radius in pixels - prevents huge splats from dominating.
     * @param {number} [options.globalOpacity=1.0] Global opacity multiplier for all splats (0.0 to 1.0).
     * @param {number} [options.sigmaCoverage=2.0] Sigma multiplier for splat quad size (2.0 = SuperSplat default).
     * @param {boolean} [options.adaptiveSigma=true] Enable adaptive sigma - reduces quad size for small splats to reduce overdraw.
     * @param {number} [options.adaptiveSigmaThreshold=8.0] Threshold in pixels for adaptive sigma - splats below this get reduced quads.
     * @param {boolean} [options.srgbToLinear=false] Convert splat colors from sRGB to linear color space.
     * @param {number} [options.exposure=1.0] Exposure/brightness multiplier (0.1 to 3.0).
     * @param {number} [options.contrast=1.0] Contrast adjustment (0.5 = flat, 1.0 = normal, 2.0 = high).
     * @param {number} [options.saturation=1.0] Color saturation (0 = grayscale, 1 = normal, 2 = oversaturated).
     * @param {number} [options.vibrance=0.0] Selective saturation for muted colors (-1 to 1).
     * @param {number} [options.highlights=0.0] Highlight adjustment (-1 to 1).
     * @param {number} [options.shadows=0.0] Shadow lift adjustment (-1 to 1).
     * @param {number} [options.shStrength=1.0] SH strength - controls view-dependent color intensity (0=flat, 1=normal, >1=exaggerated).
     * @param {number} [options.shSpecularIntensity=1.0] SH specular intensity for lit mode - scales SH contribution in specular path (0=no specular, 1=normal).
     * @param {number} [options.roughness=0.5] Surface roughness for lit mode PBR (0=mirror, 1=fully rough).
     * @param {number} [options.metalness=0.0] Surface metalness for lit mode PBR (0=dielectric, 1=metal).
     * @param {number} [options.alphaBoost=1.0] Alpha boost - increases opacity via power function (1=normal, >1=more opaque, reduces see-through).
     * @param {boolean} [options.premultiplied=false] Premultiply color by alpha in unlit mode (required for standard alpha blending).
     */
    constructor(splats: GaussianSplats, options?: {
        lightingMode?: string;
        alphaClip?: number;
        minPixelRadius?: number;
        maxPixelRadius?: number;
        globalOpacity?: number;
        sigmaCoverage?: number;
        adaptiveSigma?: boolean;
        adaptiveSigmaThreshold?: number;
        srgbToLinear?: boolean;
        exposure?: number;
        contrast?: number;
        saturation?: number;
        vibrance?: number;
        highlights?: number;
        shadows?: number;
        shStrength?: number;
        shSpecularIntensity?: number;
        roughness?: number;
        metalness?: number;
        alphaBoost?: number;
        premultiplied?: boolean;
    });
    /** Flag for type checking. */
    isGaussianSplatsMaterial: boolean;
    /** Reference to the splats instance. */
    _splats: GaussianSplats;
    /** Lighting mode: 'unlit' (SH as emissive) or 'lit' (SH as base color with PBR). */
    _lightingMode: string;
    /** Alpha clip threshold uniform - discards low-opacity splats (0 = disabled) */
    _alphaClipUniform: any;
    /** Minimum pixel radius uniform - splats smaller than this are culled (removes noise) */
    _minPixelRadiusUniform: any;
    /** Maximum pixel radius uniform - prevents huge splats from dominating (SparkJS default: 1000) */
    _maxPixelRadiusUniform: any;
    /** Global opacity uniform - multiplier for all splat opacities (0.0 to 1.0) */
    _globalOpacityUniform: any;
    /** Sigma coverage uniform - controls quad size multiplier (2.0 = SuperSplat default for optimal visual quality) */
    _sigmaCoverageUniform: any;
    /** Whether adaptive sigma is enabled - reduces quad size for small splats to reduce overdraw */
    _adaptiveSigma: boolean;
    /** Threshold for adaptive sigma - splats below this radius (in pixels) get reduced sigma (default: 8.0) */
    _adaptiveSigmaThreshold: number;
    /** Whether to premultiply color by alpha (for unlit mode blending) */
    _premultiplied: boolean;
    /** Exposure uniform - brightness multiplier (0.1-3.0) */
    _exposureUniform: any;
    /** Contrast uniform - tonal range adjustment (0.5 = flat, 1.0 = normal, 2.0 = high) */
    _contrastUniform: any;
    /** Saturation uniform - color intensity (0 = grayscale, 1 = normal, 2 = oversaturated) */
    _saturationUniform: any;
    /** Vibrance uniform - selective saturation for muted colors (-1 to 1) */
    _vibranceUniform: any;
    /** Highlights uniform - bright area adjustment (-1 to 1) */
    _highlightsUniform: any;
    /** Shadows uniform - dark area lift (-1 to 1) */
    _shadowsUniform: any;
    /** SH strength uniform - controls view-dependent color intensity (0=flat, 1=normal, >1=exaggerated) */
    _shStrengthUniform: any;
    /** Alpha boost uniform - increases opacity via power function (1=normal, >1=more opaque) */
    _alphaBoostUniform: any;
    /** SH specular intensity uniform - scales SH contribution in specular path for lit mode */
    _shSpecularIntensityUniform: any;
    /** Roughness uniform - surface roughness for lit mode PBR (0=mirror, 1=fully rough) */
    _roughnessUniform: any;
    /** Metalness uniform - surface metalness for lit mode PBR (0=dielectric, 1=metal) */
    _metalnessUniform: any;
    /** Debug mode uniform - controls debug visualization (see GaussianSplatsDebugMode) */
    _debugModeUniform: any;
    /** Whether tile-based culling is enabled */
    _tileCulling: boolean;
    /** Tile culling uniforms - set from tile binner */
    _tileCullingUniforms: any;
    /** Tile buffer storage nodes - set from tile binner */
    _tileBufferNodes: any;
    /** Custom position modifier node - takes (position, splatIdx) returns modified position */
    customPositionNode: any;
    depthTest: boolean;
    transparent: boolean;
    depthWrite: boolean;
    blendEquation: any;
    blendSrc: any;
    blendDst: any;
    side: any;
    /**
     * Build TSL shader nodes.
     * @private
     */
    private _buildNodes;
    vertexNode: any;
    normalNode: Node;
    depthNode: Node;
    receivedShadowPositionNode: Node;
    castShadowPositionNode: Node;
    /**
     * Build the opacity node with visibility and boundary masking.
     * Handles discards via opacity masks + alphaTest.
     * @private
     */
    private _buildOpacityNode;
    opacityNode: any;
    /**
     * Apply lighting mode to color/emissive nodes.
     * Color processing in linear space - tonemapping should be applied by renderer post-process.
     * @private
     */
    private _applyLightingMode;
    colorNode: any;
    outputNode: any;
    emissiveNode: any;
    specularColorNode: any;
    lights: boolean;
    roughnessNode: any;
    metalnessNode: any;
    /**
     * Set the lighting mode.
     * - 'unlit': DC + SH combined as emissive (no PBR lighting, default)
     * - 'lit': DC as diffuse albedo (colorNode), SH as specular color (specularColorNode)
     *   In lit mode, DC receives diffuse lights and envmap, while SH drives specular highlights.
     * @param {string} value - Lighting mode.
     */
    set lightingMode(value: string);
    /**
     * Get the current lighting mode.
     * @returns {string} The lighting mode ('unlit' or 'lit').
     */
    get lightingMode(): string;
    needsUpdate: boolean;
    /**
     * Set the alpha clip threshold for per-splat culling.
     * Splats with base opacity below this value are entirely discarded.
     * Higher values = fewer outlier splats but may lose detail.
     * Lower values = more detail but may show stray splats.
     * @param {number} value - Opacity threshold (0.0 to 1.0).
     */
    set alphaClip(value: number);
    /**
     * Get the current alpha clip threshold.
     * @returns {number} The alpha threshold below which splats are discarded.
     */
    get alphaClip(): number;
    /**
     * Set the minimum pixel radius for splats.
     * Splats smaller than this are culled to remove noise.
     * @param {number} value - Minimum radius in pixels (default: 2.0).
     */
    set minPixelRadius(value: number);
    /**
     * Get the minimum pixel radius for splats.
     * @returns {number} The minimum splat radius in pixels.
     */
    get minPixelRadius(): number;
    /**
     * Set the maximum pixel radius for splats.
     * Prevents extremely large splats from dominating the scene.
     * @param {number} value - Maximum radius in pixels (default: 1000).
     */
    set maxPixelRadius(value: number);
    /**
     * Get the maximum pixel radius for splats.
     * @returns {number} The maximum splat radius in pixels.
     */
    get maxPixelRadius(): number;
    /**
     * Set the global opacity multiplier.
     * Scales all splat opacities uniformly.
     * @param {number} value - Opacity multiplier (0.0 = invisible, 1.0 = full opacity).
     */
    set globalOpacity(value: number);
    /**
     * Get the global opacity multiplier.
     * @returns {number} The global opacity (0.0 to 1.0).
     */
    get globalOpacity(): number;
    /**
     * Set the sigma coverage for splat quad size.
     * Controls how many standard deviations the quad covers.
     * - 2.0: SuperSplat default (optimal visual quality)
     * - 3.0: Standard 3DGS (covers 99.7% of Gaussian, more overdraw)
     * @param {number} value - Sigma multiplier (typically 1.5 to 3.0).
     */
    set sigmaCoverage(value: number);
    /**
     * Get the sigma coverage value.
     * @returns {number} The sigma multiplier for quad size (2.0 = SuperSplat default).
     */
    get sigmaCoverage(): number;
    /**
     * Set whether adaptive sigma is enabled.
     * When enabled, splats smaller than adaptiveSigmaThreshold get reduced quad size.
     * This reduces overdraw for scenes with many small splats.
     * @param {boolean} value - Whether to enable adaptive sigma.
     */
    set adaptiveSigma(value: boolean);
    /**
     * Get whether adaptive sigma is enabled.
     * When enabled, small splats get reduced quad size to minimize overdraw.
     * @returns {boolean} Whether adaptive sigma is enabled.
     */
    get adaptiveSigma(): boolean;
    /**
     * Set the adaptive sigma threshold in pixels.
     * Splats with screen radius below this threshold get progressively smaller quads.
     * @param {number} value - Threshold in pixels (default: 8.0).
     */
    set adaptiveSigmaThreshold(value: number);
    /**
     * Get the adaptive sigma threshold in pixels.
     * @returns {number} The threshold below which splats get reduced sigma.
     */
    get adaptiveSigmaThreshold(): number;
    /**
     * Set the exposure (brightness multiplier).
     * @param {number} value - Exposure value (typically 0.1 to 3.0, default 1.0).
     */
    set exposure(value: number);
    /**
     * Get the current exposure value.
     * @returns {number} The exposure multiplier.
     */
    get exposure(): number;
    /**
     * Set the contrast adjustment.
     * @param {number} value - Contrast value (0.5 = flat, 1.0 = normal, 2.0 = high).
     */
    set contrast(value: number);
    /**
     * Get the current contrast value.
     * @returns {number} The contrast multiplier.
     */
    get contrast(): number;
    /**
     * Set the saturation adjustment.
     * @param {number} value - Saturation (0 = grayscale, 1 = normal, 2 = oversaturated).
     */
    set saturation(value: number);
    /**
     * Get the current saturation value.
     * @returns {number} The saturation multiplier.
     */
    get saturation(): number;
    /**
     * Set the vibrance (selective saturation for muted colors).
     * @param {number} value - Vibrance amount (-1 to 1, 0 = no change).
     */
    set vibrance(value: number);
    /**
     * Get the current vibrance value.
     * @returns {number} The vibrance amount.
     */
    get vibrance(): number;
    /**
     * Set the highlights adjustment.
     * @param {number} value - Highlights (-1 to 1, 0 = no change).
     */
    set highlights(value: number);
    /**
     * Get the current highlights adjustment.
     * @returns {number} The highlights value.
     */
    get highlights(): number;
    /**
     * Set the shadows adjustment (lift dark areas).
     * @param {number} value - Shadows (-1 to 1, 0 = no change).
     */
    set shadows(value: number);
    /**
     * Get the current shadows adjustment.
     * @returns {number} The shadows value.
     */
    get shadows(): number;
    /**
     * Set the SH strength - controls view-dependent color intensity.
     * @param {number} value - 0 = flat (no view-dependence), 1 = normal (default), >1 = exaggerated specular.
     */
    set shStrength(value: number);
    /**
     * Get the SH strength multiplier.
     * @returns {number} The SH strength value.
     */
    get shStrength(): number;
    /**
     * Set the alpha boost - increases splat opacity via power function.
     * Higher values make splats more opaque, reducing see-through artifacts.
     * @param {number} value - 1.0 = normal (default), >1 = more opaque (e.g., 2.0 for high SH scenes).
     */
    set alphaBoost(value: number);
    /**
     * Get the alpha boost value.
     * @returns {number} The alpha boost multiplier.
     */
    get alphaBoost(): number;
    /**
     * Set the SH specular intensity for lit mode.
     * Controls how much SH contributes to specular highlights.
     * @param {number} value - 0 = no SH specular, 1 = normal (default), >1 = exaggerated.
     */
    set shSpecularIntensity(value: number);
    /**
     * Get the SH specular intensity for lit mode.
     * @returns {number} The SH specular intensity value.
     */
    get shSpecularIntensity(): number;
    /**
     * Set the surface roughness for lit mode PBR.
     * @param {number} value - 0 = mirror smooth, 1 = fully rough (default 0.5).
     */
    set roughness(value: number);
    /**
     * Get the surface roughness for lit mode PBR.
     * @returns {number} The roughness value (0-1).
     */
    get roughness(): number;
    /**
     * Set the surface metalness for lit mode PBR.
     * @param {number} value - 0 = dielectric (default), 1 = fully metallic.
     */
    set metalness(value: number);
    /**
     * Get the surface metalness for lit mode PBR.
     * @returns {number} The metalness value (0-1).
     */
    get metalness(): number;
    /**
     * Set whether to premultiply color by alpha in unlit mode.
     * When true (default), colors are multiplied by opacity for correct alpha blending.
     * Set to false if using custom blend modes that expect non-premultiplied colors.
     * @param {boolean} value - Whether to premultiply colors.
     */
    set premultiplied(value: boolean);
    /**
     * Get whether color premultiplication is enabled.
     * @returns {boolean} Whether colors are premultiplied by alpha in unlit mode.
     */
    get premultiplied(): boolean;
    /**
     * Apply a preset configuration.
     * @param {string} presetName - Name of the preset (e.g., 'CINEMATIC', 'VIBRANT').
     */
    applyPreset(presetName: string): void;
    /**
     * Dispose of material resources.
     */
    dispose(): void;
}
